import 'server-only';
import fs from 'node:fs';
import path from 'node:path';

export type WebImage = {
  src: string;
  width: number;
  height: number;
};

const MANIFEST_PATH = path.join(process.cwd(), 'data', 'generated', 'images.json');

let manifest: Record<string, WebImage> | null = null;

// Web-sized copies are generated by scripts/optimize-images.js before dev and build.
const loadManifest = () => {
  if (manifest) return manifest;

  if (!fs.existsSync(MANIFEST_PATH)) {
    throw new Error('Missing data/generated/images.json. Run `npm run optimize:images` first.');
  }

  manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8')) as Record<string, WebImage>;
  return manifest;
};

export const getWebImage = (publicPath: string): WebImage | undefined => loadManifest()[publicPath];
